import java.io.ByteArrayInputStream;
import java.io.DataInputStream;
import java.io.IOException;
import java.io.PrintWriter;
import java.math.BigInteger;
import java.util.InputMismatchException;

public class G2V3 {
    static final int MOD = 998244353;
    static DataInputStream in;
    static PrintWriter out;
    static String INPUT = "";
    static boolean oj = System.getProperty("ONLINE_JUDGE") != null;
    static byte[] inbuf = new byte[1024];
    static int lenbuf = 0, ptrbuf = 0;

    public static void main(String[] args) throws Exception {
        in = oj ? new DataInputStream(System.in) : new DataInputStream(new ByteArrayInputStream(INPUT.getBytes()));
        out = new PrintWriter(System.out);
        long start = System.currentTimeMillis();
        solve();
        out.flush();
        if (!oj) System.out.println("[" + (System.currentTimeMillis() - start) + "ms]");
    }

    static void solve() {
        int n = ni(), m = ni();
        long inv = invl(m + 1, MOD);
        long ans = (1 + inv * n) % MOD;
        long base = inv * ((long) m * (m + 2 + (n - 1)) % MOD) % MOD;
        long u = 0;
        for (int i = 1; i <= n; i++) {
            u += invl(i, MOD);
            u %= MOD;
        }
        ans = (base * u + ans) % MOD;
        out.println(ans);
    }

    static long invl(long a, long mod) {
        if (a <= 0 || a % mod == 0) return 0;
        return BigInteger.valueOf(a % mod).modInverse(BigInteger.valueOf(mod)).longValue();
    }

    static int readByte() {
        if (lenbuf == -1) throw new InputMismatchException();
        if (ptrbuf >= lenbuf) {
            ptrbuf = 0;
            try {
                lenbuf = in.read(inbuf);
            } catch (IOException e) {
                throw new InputMismatchException();
            }
            if (lenbuf <= 0) return -1;
        }
        return inbuf[ptrbuf++];
    }

    static boolean isSpaceChar(int c) {
        return !(c >= 33 && c <= 126);
    }

    static int skip() {
        int b;
        while ((b = readByte()) != -1 && isSpaceChar(b));
        return b;
    }

    static int ni() {
        int num = 0, b;
        boolean minus = false;
        while ((b = readByte()) != -1 && !((b >= '0' && b <= '9') || b == '-'));
        if (b == '-') {
            minus = true;
            b = readByte();
        }
        while (true) {
            if (b >= '0' && b <= '9') {
                num = num * 10 + (b - '0');
            } else {
                return minus ? -num : num;
            }
            b = readByte();
        }
    }
}
